SELECT channel, CASE WHEN YEAR(order_date) < 2024 THEN 'before_2024' WHEN YEAR(order_date) = 2024 THEN '2024' ELSE 'after_2024' END order_cohort, DATE_FORMAT(order_date, 'yyyy-MM') order_month, SORT_ARRAY(COLLECT_SET(status)) status_list, MAX(order_date) last_order_date FROM orders WHERE discount > 0.17 GROUP BY channel, CASE WHEN YEAR(order_date) < 2024 THEN 'before_2024' WHEN YEAR(order_date) = 2024 THEN '2024' ELSE 'after_2024' END, DATE_FORMAT(order_date, 'yyyy-MM') ORDER BY order_cohort
